// Stryker's report on this suite:
//   [Survived] MethodExpression       Math.min(...) -> Math.max(...)
//   [Survived] ConditionalExpression  if (sum !== 0) -> if (false)
//   [Survived] UnaryOperator          cents: -cents -> cents: +cents
// and a bug from last month's code review:
//   [Survived] from/to swapped in each transfer
describe('settleUp', () => {
  test('returns no transfers when everyone is settled', () => {
    expect(settleUp({ Ana: 0, Ben: 0 })).toEqual([]);
  });

  test('returns one transfer for two people', () => {
    expect(settleUp({ Ana: 500, Ben: -500 })).toHaveLength(1);
  });
});

