const sum = (xs) => xs.reduce((a, b) => a + b, 0);

describe('settleUp', () => {
  test('returns no transfers when everyone is settled', () => {
    expect(settleUp({ Ana: 0, Ben: 0 })).toEqual([]);
  });

  test('the debtor pays the creditor the full amount', () => {
    expect(settleUp({ Ana: 500, Ben: -500 })).toEqual([
      { from: 'Ben', to: 'Ana', amountCents: 500 },
    ]);
  });

  test('one debtor pays two creditors exactly what each is owed', () => {
    const transfers = settleUp({ Ana: -1000, Ben: 600, Cai: 400 });

    expect(transfers).toEqual([
      { from: 'Ana', to: 'Ben', amountCents: 600 },
      { from: 'Ana', to: 'Cai', amountCents: 400 },
    ]);
    expect(sum(transfers.map((t) => t.amountCents))).toBe(1000);
  });

  test('refuses balances that do not add up to zero', () => {
    expect(() => settleUp({ Ana: 500, Ben: -400 })).toThrow('add up to zero');
  });
});
